parameters.query:
SELECT (
  SELECT user_id::text
  FROM telegram_accounts
  WHERE telegram_id = $1::bigint
  LIMIT 1
) AS user_id;

parameters.jsCode:
const s = $input.first().json;
const step = Number(s.current_step);
const rawText = ($('Extract message vars').first().json.text || '').toString();
const answer = rawText.trim();
const fields = ['name','age','city','description','interests','purpose','hobbies','job','education','communication_style'];
let field = (step >= 0 && step <= 9) ? fields[step] : '__invalid__';
let valid = true;
let error = '';
let value = answer;
if (!Number.isInteger(step) || step < 0) {
  valid = false;
  error = 'Произошла ошибка сессии. Нажмите /start, чтобы начать заново.';
} else if (step >= 10) {
  valid = false;
  error = 'Анкета уже заполнена и ожидает модерации.';
} else {
  const isSkip = /^(пропустить|пропуск|skip|-|нет)$/i.test(answer);
  if (step >= 6 && isSkip) {
    value = null;
  } else if (step === 0) {
    if (!answer) { valid = false; error = 'Имя не может быть пустым. Как тебя зовут?'; }
  } else if (step === 1) {
    const n = parseInt(answer, 10);
    if (!/^[0-9]{1,3}$/.test(answer) || n < 18 || n > 100) { valid = false; error = 'Возраст должен быть числом от 18 до 100. Сколько тебе лет?'; } else { value = n; }
  } else if (step === 2) {
    if (!answer) { valid = false; error = 'Город не может быть пустым. В каком городе живёшь?'; }
  } else if (step === 3) {
    if (!answer) { valid = false; error = 'Расскажи немного о себе.'; }
  } else if (step === 4) {
    const interests = answer.split(',').map(function (x) { return x.trim(); }).filter(function (x) { return x; });
    if (interests.length === 0) { valid = false; error = 'Укажи хотя бы один интерес.'; } else { value = interests; }
  } else if (step === 5) {
    if (!answer) { valid = false; error = 'Укажи цель знакомства.'; }
  } else {
    if (!answer) { value = null; }
  }
}
const nextStep = valid ? step + 1 : step;
const valueJson = JSON.stringify(value === undefined ? null : value);

return [{ json: {
  valid: valid,
  error_message: error,
  field_name: field,
  field_path: '{' + field + '}',
  field_value_json: valueJson,
  current_step: step,
  next_step: nextStep,
  session_id: s.session_id,
  user_id: s.user_id,
  chat_id: $('Extract message vars').first().json.chat_id,
  finalize: valid && nextStep >= 10
} }];
